"""Product model — raw dict based, needs migration to dataclass."""
from typing import Optional


def create_product(name: str, price: float, stock: int = 0) -> dict:
    """Create a raw product dict."""
    return {"name": name, "price": price, "stock": stock}


def get_product_name(product: dict) -> str:
    return product["name"]


def get_product_price(product: dict) -> float:
    return product["price"]


def update_stock(product: dict, delta: int) -> dict:
    """Add delta to stock (can be negative to remove)."""
    new_product = dict(product)
    new_product["stock"] = product["stock"] + delta
    return new_product


def is_in_stock(product: dict) -> bool:
    return product["stock"] > 0


def format_product(product: dict) -> str:
    return f"{product['name']}: ${product['price']:.2f} ({product['stock']} in stock)"
